actions.script:
const old=ec.artifactExecution.disableAuthz()
try{
    const row=ec.entity.find('mantle.forum.ForumAttachment').condition({attachmentId,communicationEventId:null}).forUpdate(true).one()
    removed=false
    if(row && row.expiresAt && ec.user.timestampMillis(row.expiresAt)<=ec.user.timestampMillis(ec.user.nowTimestamp)){
        ec.resource.getLocationReference(row.location).delete();row.delete();removed=true
    }
}finally{if(!old)ec.artifactExecution.enableAuthz()}

const old=ec.artifactExecution.disableAuthz()
try{
    const expired=ec.entity.find('mantle.forum.ForumAttachment').condition('communicationEventId',null).condition('expiresAt','less-equals',ec.user.nowTimestamp).orderBy('expiresAt,attachmentId').limit(100).list()
    removedCount=0;failedAttachmentIds=[]
    for(const item of expired){
        try{const out=ec.service.sync().throwOnError(true).name('mantle.forum.MediaWorkerServices.remove#ExpiredAttachment').parameters({attachmentId:item.attachmentId}).requireNewTransaction(true).call();if(out.removed)removedCount++}
        catch(error){ec.message.clearErrors();ec.logger.error('Forum staged attachment '+item.attachmentId+' could not be removed');failedAttachmentIds.push(item.attachmentId)}
    }
}finally{if(!old)ec.artifactExecution.enableAuthz()}
